/*
 * Service worker: browser notifications, and one page for when there is no
 * connection.
 *
 * Hand-written and served from /public rather than generated by a PWA plugin.
 *
 * It caches exactly two files, both the same for every visitor: the offline
 * page and the app icon it shows. No page of the site, no API answer and
 * nothing about a person is ever stored, because a worker that starts caching
 * pages is a worker that can show a sold vehicle to somebody days later, or
 * one person's form to another. The site gets its freshness from the server.
 *
 * The `fetch` handler below answers only for page loads (a tap on a link from
 * outside the app, a reload, opening the app). It asks the network exactly as
 * the browser would have, and only if the network cannot be reached at all
 * does it show the offline page instead of the browser's own error screen.
 * Every other request (scripts, photos, form posts, API calls) is not touched:
 * the handler returns without answering and the browser carries on by itself.
 */

const OFFLINE_CACHE = "offline-v1";
const OFFLINE_URL = "/offline.html";
const OFFLINE_FILES = [OFFLINE_URL, "/icons/icon-192.png"];

const FALLBACK_ICON = "/icons/icon-192.png";
// White on clear: Android tints it and shows it in the status bar.
const BADGE = "/icons/badge-96.png";

self.addEventListener("install", (event) => {
  // `reload` skips the browser's own cache, so a new version of this file
  // always fetches the current offline page. If that fails (installed while
  // the connection is poor), the worker still installs: notifications must
  // not depend on it.
  event.waitUntil(
    caches
      .open(OFFLINE_CACHE)
      .then((cache) =>
        cache.addAll(OFFLINE_FILES.map((url) => new Request(url, { cache: "reload" }))),
      )
      .catch(() => {}),
  );
  // Take over straight away rather than waiting for every tab to close, so a
  // fix to this file reaches people on their next visit and not eventually.
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      // Remove any cache an older version of this file left behind.
      const names = await caches.keys();
      await Promise.all(
        names.filter((name) => name !== OFFLINE_CACHE).map((name) => caches.delete(name)),
      );
      // Lets the browser start a page load while this worker wakes up, so
      // being in the path of page loads costs no time.
      if (self.registration.navigationPreload) {
        await self.registration.navigationPreload.enable();
      }
      await self.clients.claim();
    })(),
  );
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  // Page loads only. Returning without calling respondWith leaves the request
  // to the browser, exactly as if this handler did not exist.
  if (request.mode !== "navigate" || request.method !== "GET") return;

  event.respondWith(
    (async () => {
      try {
        const preloaded = await event.preloadResponse;
        if (preloaded) return preloaded;
        // Whatever the server says, including its own error pages, goes
        // through untouched. Nothing is stored.
        return await fetch(request);
      } catch (error) {
        // Thrown only when the network could not be reached.
        const cache = await caches.open(OFFLINE_CACHE);
        const offline = await cache.match(OFFLINE_URL);
        if (offline) return offline;
        throw error;
      }
    })(),
  );
});

self.addEventListener("push", (event) => {
  // A push with no body, or one that is not the JSON we send, still deserves
  // to show something rather than throwing inside the worker — some push
  // services send an empty message to check the subscription is alive.
  let payload = {};
  if (event.data) {
    try {
      payload = event.data.json();
    } catch {
      payload = { body: event.data.text() };
    }
  }

  const title = payload.title || "Adedayo Aremu Autos";
  const options = {
    body: payload.body || "",
    icon: payload.icon || FALLBACK_ICON,
    badge: BADGE,
    // Where a tap should land, read back in notificationclick below.
    data: { url: payload.url || "/" },
    // Replaces rather than stacks when several arrive on the same subject, so
    // adding six cars in an afternoon does not leave six notifications behind.
    tag: payload.tag || undefined,
    renotify: Boolean(payload.tag),
    timestamp: Date.now(),
  };

  event.waitUntil(self.registration.showNotification(title, options));
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const target = (event.notification.data && event.notification.data.url) || "/";

  event.waitUntil(
    (async () => {
      const all = await self.clients.matchAll({
        type: "window",
        includeUncontrolled: true,
      });

      // Reuse a tab that is already on this site instead of opening a second
      // one — people end up with a row of identical tabs otherwise.
      for (const client of all) {
        const sameOrigin = new URL(client.url).origin === self.location.origin;
        if (sameOrigin && "focus" in client) {
          await client.focus();
          if ("navigate" in client) {
            try {
              await client.navigate(target);
            } catch {
              /* Navigation can be refused; the tab is focused either way. */
            }
          }
          return;
        }
      }

      if (self.clients.openWindow) await self.clients.openWindow(target);
    })(),
  );
});

/*
 * The browser can retire a subscription on its own — a push service rotating
 * keys, a long silence — and hands the page a new one here. Re-registering
 * immediately keeps the row in step instead of leaving a dead endpoint that
 * only shows up as a delivery failure weeks later.
 */
self.addEventListener("pushsubscriptionchange", (event) => {
  event.waitUntil(
    (async () => {
      const applicationServerKey =
        (event.oldSubscription && event.oldSubscription.options &&
          event.oldSubscription.options.applicationServerKey) || undefined;
      if (!applicationServerKey) return;

      const fresh = await self.registration.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey,
      });

      await fetch("/api/push/subscribe", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          subscription: fresh.toJSON(),
          replaces: event.oldSubscription ? event.oldSubscription.endpoint : null,
        }),
      });
    })(),
  );
});
